<?php
require_once __DIR__ . '/../helpers.php'; require_once __DIR__ . '/../config/database.php'; require_admin();
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=$_POST['role']??'staff';if(!preg_match('/^[A-Za-z0-9_.-]{3,50}$/',$username))$error='Username 3–50 karakter, gunakan huruf/angka/._-.';elseif(strlen($password)<8)$error='Password minimal 8 karakter.';elseif(!in_array($role,['admin','staff'],true))$error='Role tidak valid.';else{try{$s=$pdo->prepare('INSERT INTO users(username,password_hash,role) VALUES(?,?,?)');$s->execute([$username,password_hash($password,PASSWORD_DEFAULT),$role]);flash('Pengguna berhasil ditambahkan.');redirect('users.php');}catch(PDOException $e){$error='Username sudah digunakan atau data tidak valid.';}}}
$rows=$pdo->query('SELECT id,username,role,created_at FROM users ORDER BY id')->fetchAll();layout_start('Pengguna');if($error)echo '<div class="alert error">'.e($error).'</div>';echo '<div class="card"><h2>Tambah Pengguna</h2><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><label>Username</label><input name="username" required minlength="3" maxlength="50"><label>Password (minimal 8 karakter)</label><input type="password" name="password" required minlength="8"><label>Role</label><select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select><p><button>Tambah Pengguna</button></p></form></div><div class="card table-wrap"><table><tr><th>Username</th><th>Role</th><th>Dibuat</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['username']).'</td><td>'.e($r['role']).'</td><td>'.e($r['created_at']).'</td></tr>';echo '</table></div>';layout_end();
